import math

def cosine_similarity(a, b):
    dot = sum(x * y for x, y in zip(a, b))
    norm_a = math.sqrt(sum(x * x for x in a))
    norm_b = math.sqrt(sum(y * y for y in b))
    if norm_a == 0 or norm_b == 0:
        return 0.0
    return dot / (norm_a * norm_b)

def top_k(query, docs, k):
    scored = [(i, cosine_similarity(query, d)) for i, d in enumerate(docs)]
    scored.sort(key=lambda pair: pair[1], reverse=True)
    return [i for i, _ in scored[:k]]

def validate_args(args, schema):
    errors = []
    validated = {}

    for name, spec in schema.items():
        required = spec.get("required", False)
        expected = spec["type"]

        if name not in args:
            if required:
                errors.append(f"missing required field '{name}'")
            continue

        value = args[name]
        if isinstance(value, expected):
            validated[name] = value
        else:
            try:
                validated[name] = expected(value)
            except (ValueError, TypeError):
                errors.append(
                    f"field '{name}' expected {expected.__name__}, "
                    f"got {type(value).__name__}"
                )

    if errors:
        raise ValueError("; ".join(errors))
    return validated

VALID_ROLES = {"system", "user", "assistant", "tool"}

def build_messages(system_prompt, user_message, history=None):
    history = history or []

    for m in history:
        if m["role"] not in VALID_ROLES:
            raise ValueError(f"invalid role: {m['role']}")

    messages = [{"role": "system", "content": system_prompt}]
    messages.extend(history)
    messages.append({"role": "user", "content": user_message})
    return messages

import json
import re

def extract_json(text):
    # 1. Try direct parse
    try:
        return json.loads(text)
    except json.JSONDecodeError:
        pass

    # 2. Strip markdown code fences
    fenced = re.search(r"```(?:json)?\s*(.*?)```", text, re.DOTALL)
    if fenced:
        try:
            return json.loads(fenced.group(1).strip())
        except json.JSONDecodeError:
            pass

    # 3. Extract the first balanced {...} object
    start = text.find("{")
    if start != -1:
        depth = 0
        for i in range(start, len(text)):
            if text[i] == "{":
                depth += 1
            elif text[i] == "}":
                depth -= 1
                if depth == 0:
                    candidate = text[start:i + 1]
                    return json.loads(candidate)

    raise ValueError("no valid JSON object found in output")

